                Blocks(Paragraph(Text("The child is obtained from the actual adaptive radius-four transition. Missing directions have zero coefficients. All finite checks are performed on 881 actual rows."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("hc-affine-row-witness"),
